func (s *AIService) ChatWithUserStream(stream grpc.ClientStreamingServer[pb.ChatMsg, pb.ChatMsg]) error {
    respMsg := ""
    for {
        chatReq, err := stream.Recv()
        if err == io.EOF {
            return stream.SendAndClose(&pb.ChatMsg{Msg: respMsg})
        }
        respMsg = respMsg + chatReq.Msg
    }
}

