func (s *AIService) ChatWithUserAIStream(stream grpc.BidiStreamingServer[pb.ChatMsg, pb.ChatMsg]) error {
    for {
        chatReq, err := stream.Recv()
        if err == io.EOF {
            break
        }
        if err != nil {
            return err
        }
        replyMsg := replace(chatReq.Msg)  // 文本转换
        stream.Send(&pb.ChatMsg{Msg: replyMsg})
    }
    return nil
}
